/* Runtime of the C side of the TU state oracle (rust/melee_modes/src/oracle.rs mirrors every
 * byte of the recorder behaviour; change both together).
 *
 * The driver generated by run.py `#include`s the real game TU, defines thunks that call its
 * functions, and hands the tables to rt_main. This file loads the Rust-exported cases
 * (target/cref/tu_<stem>.cases), maps the arena at the same virtual address as the Rust process,
 * runs each case and prints
 *     R <func> <case> <ret> <state-hash> <log-hash> <ncalls>
 * which the Rust test compares against its own run of the port.
 * Compiled with -ffp-contract=off (the recorder's float arithmetic is explicit). */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>
#include <setjmp.h>
#include <windows.h>

typedef unsigned long long u64;
typedef long long s64;
typedef unsigned int u32;

typedef struct { const char* name; void* addr; u64 size; } RtGlobal;
typedef struct { const char* name; void* addr; } RtFn;
typedef struct { const char* name; u64 (*thunk)(const u64*); } RtFunc;

#define FNV_OFF 0xcbf29ce484222325ULL
#define FNV_PRIME 0x00000100000001b3ULL

static u64 fnv_str(const char* s) {
    u64 h = FNV_OFF;
    for (; *s; s++) { h ^= (unsigned char)*s; h *= FNV_PRIME; }
    return h;
}
static u64 mixw(u64 h, u64 w) { return (h ^ w) * FNV_PRIME; }
static u64 splitmix(u64 x) {
    u64 z = x + 0x9E3779B97F4A7C15ULL;
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}

#define ARENA_BASE 0x0000020000000000ULL
#define ARENA_SIZE (32ULL << 20)
#define GLOBALS_BASE 0x1000ULL

static unsigned char* arena;

/* ---- tables ------------------------------------------------------------------------------ */
typedef struct { const char* name; u64 addr; u64 size; u64 off; int rw; int rp; u64 tagbase; } G;
typedef struct { const char* name; u64 addr; u64 tag; } F;
static G g_tab[4096]; static int g_n;
static F f_tab[4096]; static int f_n;
static u64 heap_start;

static u64 fn_tag(const char* n) { return 0xF100000000000000ULL | (fnv_str(n) & 0xFFFFFFFFULL); }
static u64 glob_tag(const char* n) { return 0xF200000000000000ULL | ((fnv_str(n) & 0xFFFFFFULL) << 32); }

static u64 norm(u64 w) {
    int i;
    if (w < 0x10000) return w;
    for (i = 0; i < f_n; i++) if (f_tab[i].addr == w) return f_tab[i].tag;
    for (i = 0; i < g_n; i++) if (w >= g_tab[i].addr && w < g_tab[i].addr + g_tab[i].size) return g_tab[i].tagbase | (w - g_tab[i].addr);
    return w;
}
static u64 norm_ptr(u64 w) {
    u64 n;
    if (w == 0) return 0;
    if (w >= ARENA_BASE && w < ARENA_BASE + ARENA_SIZE) return 0xF300000000000000ULL | (w - ARENA_BASE);
    n = norm(w);
    if (n != w) return n;
    return 0xF400000000000000ULL;
}
static int is_foreign(u64 w) {
    return w >= 0x10000ULL && w < 0x0000800000000000ULL && !(w >= ARENA_BASE && w < ARENA_BASE + ARENA_SIZE);
}
/* tag -> this process's address (image decoding) */
static u64 denorm(u64 w) {
    int i;
    u64 top = w >> 56;
    if (top == 0xF1) { for (i = 0; i < f_n; i++) if (f_tab[i].tag == w) return f_tab[i].addr; }
    else if (top == 0xF2) {
        for (i = 0; i < g_n; i++) if ((w & 0xFFFFFFFF00000000ULL) == g_tab[i].tagbase) return g_tab[i].addr + (w & 0xFFFFFFFFULL);
    }
    return w;
}

/* ---- specs and the recorder -------------------------------------------------------------- */
typedef struct { char name[96]; int kind; /*0 int 1 ptr 2 pool 3 seq 4 flt 5 dbl*/ s64 lo, hi; u64 val; u64 seq[256]; int nseq; } RetS;
typedef struct { char name[96]; int idx; int nb; } ArgS;
static RetS rets[64]; static int nrets;
static ArgS outs[32]; static int nouts;
static ArgS strs[32]; static int nstrs;
static ArgS mems[32]; static int nmems;
typedef struct { char name[96]; int idx; int n; u64 v[64]; } OutV;
static OutV outvs[16]; static int noutvs;

static u64 rec_seed, rec_log, rec_calls, rec_hwm;
static struct { u64 nh; u64 n; } counts[1024]; static int ncounts;
static int trace; static int verbose;

static u64 stream(u64 nh) {
    int i; u64 n;
    for (i = 0; i < ncounts; i++) if (counts[i].nh == nh) break;
    if (i == ncounts) { counts[i].nh = nh; counts[i].n = 0; ncounts++; }
    n = counts[i].n++;
    return splitmix(rec_seed ^ (nh * 0x9E3779B97F4A7C15ULL) ^ (n * 0xD6E8FEB86659FD93ULL));
}
static u64 count_of(u64 nh) {
    int i;
    for (i = 0; i < ncounts; i++) if (counts[i].nh == nh) return counts[i].n;
    return 0;
}
static u64 pool(u64 n) {
    u64 off = (rec_hwm + 15) & ~15ULL;
    rec_hwm = off + n;
    if (rec_hwm > ARENA_SIZE) { fprintf(stderr, "pool exhausted\n"); exit(2); }
    if (verbose) { int q; fprintf(stderr, "  pool %llx:", ARENA_BASE + off); for (q = 0; q < 8; q++) fprintf(stderr, " %llx", ((u64*)(arena + off))[q]); fprintf(stderr, "\n"); }
    return ARENA_BASE + off;
}

/* current call */
static const char* cur_name; static u64 cur_nh; static int cur_nargs; static u64 cur_args[16]; static int cur_kinds[16];
static char trbuf[1024]; static int trlen;

void rt_begin(const char* name) {
    cur_name = name; cur_nh = fnv_str(name); cur_nargs = 0;
    if (verbose) { fprintf(stderr, "  call %s\n", name); fflush(stderr); }
    rec_calls++;
    rec_log = mixw(rec_log, cur_nh);
    trlen = 0;
    if (trace) trlen += sprintf(trbuf + trlen, "CALL %s", name);
}
static void arg_common(u64 n, int kind, u64 raw) {
    rec_log = mixw(rec_log, n);
    if (trace) trlen += sprintf(trbuf + trlen, " %llx", n);
    if (cur_nargs < 16) { cur_args[cur_nargs] = raw; cur_kinds[cur_nargs] = kind; }
    cur_nargs++;
}
void rt_arg_i(u64 v, int bits) { if (bits < 64) v &= ((1ULL << bits) - 1); arg_common(v, 0, v); }
void rt_arg_p(const void* p) {
    int i; int idx = cur_nargs;
    u64 raw = (u64)(uintptr_t)p;
    arg_common(norm_ptr(raw), 1, raw);
    if (raw == 0) return;
    for (i = 0; i < nstrs; i++) if (!strcmp(strs[i].name, cur_name) && strs[i].idx == idx) {
        u64 h = FNV_OFF; int j;
        for (j = 0; j < 256; j++) { unsigned char c = ((const unsigned char*)p)[j]; if (!c) break; h = (h ^ c) * FNV_PRIME; }
        rec_log = mixw(rec_log, h);
        if (trace) trlen += sprintf(trbuf + trlen, " str:%llx", h);
    }
    for (i = 0; i < nmems; i++) if (!strcmp(mems[i].name, cur_name) && mems[i].idx == idx) {
        u64 h = FNV_OFF; int j;
        for (j = 0; j < mems[i].nb; j++) h = (h ^ ((const unsigned char*)p)[j]) * FNV_PRIME;
        rec_log = mixw(rec_log, h);
        if (trace) trlen += sprintf(trbuf + trlen, " mem:%llx", h);
    }
}
void rt_arg_f(float f) { u32 b; memcpy(&b, &f, 4); arg_common((u64)b, 2, (u64)b); }
void rt_arg_d(double d) { u64 b; memcpy(&b, &d, 8); arg_common(b, 3, b); }


/* printf-style varargs: count and kinds come from the format string at argument `fmtidx`
 * (oracle.rs `fmt_convs` / `ext_call_va` mirror this). */
static void logw(u64 n) {
    rec_log = mixw(rec_log, n);
    if (trace) trlen += sprintf(trbuf + trlen, " %llx", n);
}
static u64 strhash_at(u64 w) {
    u64 h = FNV_OFF; int j; const unsigned char* p = (const unsigned char*)(uintptr_t)w;
    if (!w) return h;
    for (j = 0; j < 256; j++) { unsigned char c = p[j]; if (!c) break; h = (h ^ c) * FNV_PRIME; }
    return h;
}
void rt_va(va_list* ap, int fmtidx) {
    const unsigned char* fmt = (const unsigned char*)(uintptr_t)cur_args[fmtidx];
    int i = 0; unsigned char c;
    for (;;) {
        int lng = 0;
        c = fmt[i]; if (!c) break; i++;
        if (c != '%') continue;
        if (fmt[i] == '%') { i++; continue; }
        for (;;) {
            u64 w;
            c = fmt[i]; if (!c) break; i++;
            if (c == '*') { w = va_arg(*ap, u64); logw(w & 0xFFFFFFFFULL); continue; }
            if (c == 'l' || c == 'j' || c == 'z' || c == 't' || c == 'q' || c == 'L' || c == 'I') { lng = 1; continue; }
            if (c == 'd' || c == 'i' || c == 'u' || c == 'o' || c == 'x' || c == 'X' || c == 'c') { w = va_arg(*ap, u64); logw(lng ? w : (w & 0xFFFFFFFFULL)); break; }
            if (c == 's') { w = va_arg(*ap, u64); logw(norm_ptr(w)); logw(strhash_at(w)); break; }
            if (c == 'p') { w = va_arg(*ap, u64); logw(norm_ptr(w)); break; }
            if (c == 'f' || c == 'F' || c == 'e' || c == 'E' || c == 'g' || c == 'G' || c == 'a' || c == 'A') { w = va_arg(*ap, u64); logw(w); break; }
            if (c == 'n') break;
        }
    }
}

/* varargs of fixed kinds: 'i' int (32 bits), 'q' 64-bit int, 'd' double, 'p' pointer, 's' string */
void rt_va_kinds(va_list* ap, const char* kinds) {
    for (; *kinds; kinds++) {
        u64 w = va_arg(*ap, u64);
        if (*kinds == 'i') logw(w & 0xFFFFFFFFULL);
        else if (*kinds == 'p') logw(norm_ptr(w));
        else if (*kinds == 's') { logw(norm_ptr(w)); logw(strhash_at(w)); }
        else logw(w);
    }
}

void rt_args_end(void) {
    int i;
    for (i = 0; i < noutvs; i++) if (!strcmp(outvs[i].name, cur_name) && outvs[i].idx < cur_nargs && cur_args[outvs[i].idx] != 0) {
        u64 key = cur_nh ^ 0x7777ULL; int c2, k;
        for (c2 = 0; c2 < ncounts; c2++) if (counts[c2].nh == key) break;
        if (c2 == ncounts) { counts[c2].nh = key; counts[c2].n = 0; ncounts++; }
        k = (int)(counts[c2].n++ % (u64)outvs[i].n);
        *(u64*)(uintptr_t)cur_args[outvs[i].idx] = outvs[i].v[k];
    }
    for (i = 0; i < nouts; i++) if (!strcmp(outs[i].name, cur_name) && outs[i].idx < cur_nargs && cur_args[outs[i].idx] != 0) {
        unsigned char* p = (unsigned char*)(uintptr_t)cur_args[outs[i].idx];
        u64 x = stream(cur_nh ^ 0x5555ULL); int j = 0;
        while (j < outs[i].nb) {
            int q;
            for (q = 0; q < 8 && j + q < outs[i].nb; q++) p[j + q] = (unsigned char)(x >> (8 * q));
            j += 8; x = splitmix(x);
        }
    }
}
static RetS* find_ret(void) {
    int i;
    for (i = 0; i < nrets; i++) if (!strcmp(rets[i].name, cur_name)) return &rets[i];
    return 0;
}
static void trace_ret(u64 v) { if (trace) { printf("%s -> %llx\n", trbuf, v); } }

u64 rt_ret_i(int bits) {
    RetS* s = find_ret(); u64 x = stream(cur_nh), raw;
    if (s && s->kind == 0) raw = (u64)s->lo + x % ((u64)(s->hi - s->lo) + 1);
    else if (s && s->kind == 3) raw = s->seq[(count_of(cur_nh) - 1) % s->nseq];
    else if (s && s->kind == 1) raw = s->val;
    else raw = x % 4;
    if (bits < 64) raw &= ((1ULL << bits) - 1);
    trace_ret(raw);
    return raw;
}
void* rt_ret_p(void) {
    RetS* s = find_ret(); u64 x = stream(cur_nh), r;
    if (s && s->kind == 1) r = s->val;
    else if (s && s->kind == 2) r = pool(s->val);
    else if (s && s->kind == 3) r = s->seq[(count_of(cur_nh) - 1) % s->nseq];
    else if (s && s->kind == 0) r = (u64)s->lo + x % ((u64)(s->hi - s->lo) + 1);
    else r = pool(0x100);
    trace_ret(r);
    return (void*)(uintptr_t)r;
}
static float flt_pick(float lo, float hi, u64 x) {
    float t = (float)(x % 10001) / 10000.0f;
    float d = hi - lo;
    float m = d * t;
    return lo + m;
}
float rt_ret_f(void) {
    RetS* s = find_ret(); u64 x = stream(cur_nh); float f; u32 b;
    if (s && s->kind == 4) { u32 lo = (u32)s->lo, hi = (u32)s->hi; float flo, fhi; memcpy(&flo, &lo, 4); memcpy(&fhi, &hi, 4); f = flt_pick(flo, fhi, x); }
    else f = (float)((int)(x % 2001) - 1000) * 0.1f;
    memcpy(&b, &f, 4);
    trace_ret((u64)b);
    return f;
}
double rt_ret_d(void) {
    RetS* s = find_ret(); u64 x = stream(cur_nh); double f; u64 b;
    if (s && s->kind == 5) {
        u64 lo = (u64)s->lo, hi = (u64)s->hi; double flo, fhi, t, d, m;
        memcpy(&flo, &lo, 8); memcpy(&fhi, &hi, 8);
        t = (double)(x % 10001) / 10000.0; d = fhi - flo; m = d * t; f = flo + m;
    } else f = (double)((int)(x % 2001) - 1000) * 0.1;
    memcpy(&b, &f, 8);
    trace_ret(b);
    return f;
}
static jmp_buf case_jb;
static int is_noreturn_name(const char* n) { return !strcmp(n, "__assert") || !strcmp(n, "OSPanic") || !strcmp(n, "HSD_Panic"); }
void rt_ret_v(void) { trace_ret(0); if (is_noreturn_name(cur_name)) longjmp(case_jb, 1); }

/* thunk helpers */
float rt_f32(u64 b) { u32 x = (u32)b; float f; memcpy(&f, &x, 4); return f; }
double rt_f64(u64 b) { double f; memcpy(&f, &b, 8); return f; }
u64 rt_f32bits(float f) { u32 x; memcpy(&x, &f, 4); return x; }
u64 rt_f64bits(double f) { u64 x; memcpy(&x, &f, 8); return x; }
u64 rt_normptr(u64 p) { return norm_ptr(p); }

/* ---- file parsing ------------------------------------------------------------------------ */
static int hexval(int c) { return c <= '9' ? c - '0' : (c | 32) - 'a' + 10; }

int rt_main(int argc, char** argv, const RtGlobal* gs, int ng, const RtFn* fs, int nf, const RtFunc* fn, int nfn) {
    FILE* fp; long sz; char* text; char* line; int i;
    u64 maxused = 0;
    int const_reported[4096] = {0};
    if (argc < 2) { fprintf(stderr, "usage: exe cases [func:idx for trace]\n"); return 2; }
    if (argc > 2) trace = 1;
    verbose = getenv("ORACLE_VERBOSE") != 0;
    arena = (unsigned char*)VirtualAlloc((void*)(uintptr_t)ARENA_BASE, ARENA_SIZE, 0x3000, 0x04);
    if ((u64)(uintptr_t)arena != ARENA_BASE) { fprintf(stderr, "cannot map arena\n"); return 2; }
    for (i = 0; i < nf; i++) { f_tab[f_n].name = fs[i].name; f_tab[f_n].addr = (u64)(uintptr_t)fs[i].addr; f_tab[f_n].tag = fn_tag(fs[i].name); f_n++; }
    fp = fopen(argv[1], "rb");
    if (!fp) { fprintf(stderr, "no cases file\n"); return 2; }
    fseek(fp, 0, SEEK_END); sz = ftell(fp); fseek(fp, 0, SEEK_SET);
    text = (char*)malloc(sz + 2); fread(text, 1, sz, fp); text[sz] = 0; fclose(fp);

    /* header */
    {
        char* p = text;
        for (line = strtok(p, "\n"); line; line = strtok(0, "\n")) {
            char name[128]; unsigned long long a, b; char mode[8];
            if (line[0] == 'G' && !strncmp(line, "GLOBAL ", 7)) {
                if (sscanf(line + 7, "%127s %llx %llx %7s", name, &a, &b, mode) == 4) {
                    int k;
                    for (k = 0; k < ng; k++) if (!strcmp(gs[k].name, name)) break;
                    if (k == ng) { fprintf(stderr, "driver lacks global %s\n", name); return 2; }
                    g_tab[g_n].name = gs[k].name; g_tab[g_n].addr = (u64)(uintptr_t)gs[k].addr; g_tab[g_n].size = b;
                    g_tab[g_n].off = a; g_tab[g_n].rw = !strcmp(mode, "rw"); g_tab[g_n].rp = !strcmp(mode, "rp"); g_tab[g_n].tagbase = glob_tag(gs[k].name);
                    if (gs[k].size != b) { fprintf(stderr, "global %s: C size %llu, Rust size %llu\n", name, (u64)gs[k].size, b); return 2; }
                    g_n++;
                }
            } else if (!strncmp(line, "HEAP ", 5)) {
                sscanf(line + 5, "%llx", &heap_start);
            } else if (!strncmp(line, "CASE ", 5)) {
                break; /* header done; rewind handled below */
            }
        }
    }
    /* reparse whole file for cases (strtok clobbered it: reload) */
    fp = fopen(argv[1], "rb");
    fread(text, 1, sz, fp); text[sz] = 0; fclose(fp);
    {
        char* cur = text; int in_case = 0;
        int func = -1, idx = -1; u64 seed = 0, hwm = 0; u64 args[16]; int nargs = 0;
        const char* want_f = 0; int want_i = -1; char wantbuf[128];
        if (argc > 2) { strncpy(wantbuf, argv[2], 127); wantbuf[127] = 0; { char* c = strchr(wantbuf, ':'); if (c) { *c = 0; want_i = atoi(c + 1); } want_f = wantbuf; } }
        while (*cur) {
            char* e = strchr(cur, '\n'); char* l = cur;
            if (e) { *e = 0; cur = e + 1; } else cur += strlen(cur);
            if (!strncmp(l, "FUNC ", 5)) continue;
            if (!strncmp(l, "CASE ", 5)) {
                char* q = l + 5; int k;
                func = (int)strtol(q, &q, 10); idx = (int)strtol(q, &q, 10);
                seed = strtoull(q, &q, 16); hwm = strtoull(q, &q, 16); nargs = (int)strtol(q, &q, 10);
                for (k = 0; k < nargs; k++) args[k] = denorm(strtoull(q, &q, 16));
                memset(arena, 0, maxused);
                nrets = nouts = nstrs = nmems = noutvs = 0;
                in_case = 1;
                continue;
            }
            if (!in_case) continue;
            if (!strncmp(l, "RET ", 4)) {
                char kind[16]; RetS* r = &rets[nrets++]; char* q;
                memset(r, 0, sizeof *r);
                sscanf(l + 4, "%95s %15s", r->name, kind);
                q = l + 4 + strlen(r->name) + 1 + strlen(kind) + 1;
                if (!strcmp(kind, "int")) { r->kind = 0; r->lo = strtoll(q, &q, 10); r->hi = strtoll(q, &q, 10); }
                else if (!strcmp(kind, "ptr")) { r->kind = 1; r->val = strtoull(q, &q, 16); }
                else if (!strcmp(kind, "pool")) { r->kind = 2; r->val = strtoull(q, &q, 10); }
                else if (!strcmp(kind, "seq")) { int k; r->kind = 3; r->nseq = (int)strtol(q, &q, 10); for (k = 0; k < r->nseq; k++) r->seq[k] = strtoull(q, &q, 16); }
                else if (!strcmp(kind, "flt")) { r->kind = 4; r->lo = (s64)strtoull(q, &q, 16); r->hi = (s64)strtoull(q, &q, 16); }
                else if (!strcmp(kind, "dbl")) { r->kind = 5; r->lo = (s64)strtoull(q, &q, 16); r->hi = (s64)strtoull(q, &q, 16); }
            } else if (!strncmp(l, "OUT ", 4)) { ArgS* a = &outs[nouts++]; sscanf(l + 4, "%95s %d %d", a->name, &a->idx, &a->nb); }
            else if (!strncmp(l, "OUTV ", 5)) {
                OutV* o = &outvs[noutvs++]; char* q; int k;
                sscanf(l + 5, "%95s %d %d", o->name, &o->idx, &o->n);
                q = l + 5 + strlen(o->name) + 1;
                q = strchr(q, ' ') + 1; q = strchr(q, ' ') + 1; /* skip idx, n */
                for (k = 0; k < o->n; k++) o->v[k] = denorm(strtoull(q, &q, 16));
            }
            else if (!strncmp(l, "STR ", 4)) { ArgS* a = &strs[nstrs++]; sscanf(l + 4, "%95s %d", a->name, &a->idx); }
            else if (!strncmp(l, "MEM ", 4)) { ArgS* a = &mems[nmems++]; sscanf(l + 4, "%95s %d %d", a->name, &a->idx, &a->nb); }
            else if (!strncmp(l, "IMG ", 4)) {
                u64 off = strtoull(l + 4, 0, 16); char* h = strchr(l + 4, ' ') + 1; int k;
                for (k = 0; k < 64; k++) arena[off + k] = (unsigned char)(hexval(h[2 * k]) * 16 + hexval(h[2 * k + 1]));
            } else if (!strncmp(l, "END", 3)) {
                u64 h, end, o; int k; u64 ret;
                in_case = 0;
                if (want_f && !(!strcmp(want_f, fn[func].name) && want_i == idx)) { if (hwm + 64 > maxused) maxused = hwm + 64; continue; }
                /* decode tags to this process's addresses, in the non-ro heap and rw globals */
                if (hwm > maxused) maxused = hwm;
                for (o = GLOBALS_BASE & ~7ULL; o < hwm; o += 8) {
                    u64* w = (u64*)(arena + o); int ro = 0;
                    for (k = 0; k < g_n; k++) if (!g_tab[k].rw && o >= g_tab[k].off && o < g_tab[k].off + g_tab[k].size) ro = 1;
                    if (!ro && *w >> 60 == 0xF) *w = denorm(*w);
                }
                for (k = 0; k < g_n; k++) {
                    if (g_tab[k].rw) memcpy((void*)(uintptr_t)g_tab[k].addr, arena + g_tab[k].off, g_tab[k].size);
                    else if (!const_reported[k]) {
                        u64 n8 = g_tab[k].size / 8, j; int bad = 0;
                        for (j = 0; j < n8; j++) {
                            u64 cw = ((u64*)(uintptr_t)g_tab[k].addr)[j], rw_ = ((u64*)(arena + g_tab[k].off))[j];
                            if (norm(cw) == rw_) continue;
                            if (g_tab[k].rp && is_foreign(norm(cw)) && rw_ == 0xF400000000000000ULL) continue;
                            bad = 1; break;
                        }
                        if (!bad && memcmp((char*)(uintptr_t)g_tab[k].addr + n8 * 8, arena + g_tab[k].off + n8 * 8, g_tab[k].size - n8 * 8)) bad = 1;
                        if (bad) { printf("CONSTMISMATCH %s\n", g_tab[k].name); const_reported[k] = 1; }
                    }
                }
                rec_seed = seed; rec_log = FNV_OFF; rec_calls = 0; rec_hwm = hwm; ncounts = 0;
                if (getenv("ORACLE_VERBOSE")) { fprintf(stderr, "run %s %d\n", fn[func].name, idx); fflush(stderr); }
                if (setjmp(case_jb) == 0) ret = fn[func].thunk(args); else ret = 0xDEADDEADDEADDEADULL;
                for (k = 0; k < g_n; k++) if (g_tab[k].rw) memcpy(arena + g_tab[k].off, (void*)(uintptr_t)g_tab[k].addr, g_tab[k].size);
                end = rec_hwm > hwm ? rec_hwm : hwm; if (end < heap_start) end = heap_start;
                if (end > maxused) maxused = end;
                h = FNV_OFF;
                {
                    char dumpname[160]; snprintf(dumpname, sizeof dumpname, "%s:%d", fn[func].name, idx);
                    FILE* df = getenv("ORACLE_DUMP") && (want_f || (getenv("ORACLE_DUMPCASE") && !strcmp(getenv("ORACLE_DUMPCASE"), dumpname))) ? fopen(getenv("ORACLE_DUMP"), "wb") : 0;
                    for (o = GLOBALS_BASE & ~7ULL; o < end; o += 8) {
                        u64 nw = norm(*(u64*)(arena + o));
                        h = mixw(h, nw);
                        if (df) fwrite(&nw, 8, 1, df);
                    }
                    if (df) fclose(df);
                }
                printf("R %s %d %llx %llx %llx %llx\n", fn[func].name, idx, ret, h, rec_log, rec_calls);
                fflush(stdout);
                if (want_f) printf("state %llx\n", h);
                (void)nfn;
            }
        }
    }
    return 0;
}
